def is_valid(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping:
            top = stack.pop() if stack else '#'
            if mapping[char] != top:
                return False
        elif char in mapping.values():
            stack.append(char)
    return not stack

def main():
    s = input().strip()
    print("true" if is_valid(s) else "false")

if __name__ == '__main__':
    main()
